const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showUserSettings(user,{modal,close,toast,onSave,logout}){let photo=user.photo||'';modal(`<div class="eyebrow">ACCOUNT SETTINGS</div><h2>Cài đặt người dùng</h2><form id="user-settings-form"><div class="settings-photo-area"><div id="settings-photo-preview">${photo?`<img src="${esc(photo)}" alt="Ảnh đại diện hiện tại">`:`<span>${esc(user.name?.charAt(0)||'♡')}</span>`}</div><div><label class="settings-photo-button" for="settings-photo-file">Thay đổi ảnh đại diện</label><input id="settings-photo-file" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG hoặc WebP · Tối đa 500 KB</small><button type="button" id="settings-remove-photo">Gỡ ảnh</button></div></div><label for="settings-name">${user.accountType==='nickname'?'Thay đổi biệt danh':'Thay đổi tên'}</label><input id="settings-name" name="name" required minlength="${user.accountType==='nickname'?3:2}" maxlength="${user.accountType==='nickname'?30:100}" value="${esc(user.name)}"><label for="settings-address">Thay đổi địa chỉ / khu vực</label><input id="settings-address" name="address" maxlength="200" autocomplete="street-address" value="${esc(user.address||'')}"><label for="settings-email">Thay đổi email</label><input id="settings-email" name="emailPending" type="email" maxlength="254" autocomplete="email" value="${esc(user.emailPending||user.email||'')}" placeholder="ban@example.com"><p class="settings-email-note">${user.email?`Email đăng nhập hiện tại: <strong>${esc(user.email)}</strong>.<br>`:''}Email mới chỉ lưu dưới dạng yêu cầu chờ xác minh; chưa thay đổi email đăng nhập. Dịch vụ xác minh email đang được chuẩn bị.</p><label for="settings-phone">Thay đổi số điện thoại</label><input id="settings-phone" name="phone" type="tel" maxlength="25" autocomplete="tel" value="${esc(user.phone||'')}" placeholder="+84 912 345 678">${user.designPreview?'<p class="settings-email-note">Chế độ xây dựng: các thay đổi chỉ lưu trên trình duyệt.</p>':''}<p id="settings-error" class="form-error" role="alert"></p><button class="dark">Lưu thay đổi</button><button type="button" id="settings-logout" class="settings-logout">↪ Đăng xuất</button></form>`);
document.querySelector('#settings-logout').onclick=()=>{document.body.classList.remove('broke-mode');close();logout();};const preview=document.querySelector('#settings-photo-preview');document.querySelector('#settings-photo-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>500*1024){document.querySelector('#settings-error').textContent='Chọn ảnh PNG, JPG hoặc WebP không quá 500 KB.';event.target.value='';return;}try{photo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});preview.innerHTML=`<img src="${esc(photo)}" alt="Ảnh đại diện mới">`;document.querySelector('#settings-error').textContent='';}catch{document.querySelector('#settings-error').textContent='Không đọc được ảnh.';}};
document.querySelector('#settings-remove-photo').onclick=()=>{photo='';preview.innerHTML=`<span>${esc(user.name?.charAt(0)||'♡')}</span>`;document.querySelector('#settings-photo-file').value='';};document.querySelector('#user-settings-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('.dark');button.disabled=true;const data={...Object.fromEntries(new FormData(event.target)),photo};try{let updated;if(user.designPreview){if(data.phone&&!/^\+?[\d\s().-]{8,25}$/.test(data.phone))throw Error('Vui lòng kiểm tra số điện thoại.');updated={...user,...data};localStorage.setItem('debtfreelately-preview-settings',JSON.stringify(data));}else{const response=await fetch('/api/auth/profile',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'Không lưu được cài đặt.');updated=result.user;}onSave(updated);close();toast(data.emailPending&&data.emailPending!==user.email?'Đã lưu thông tin. Email mới đang chờ xác minh.':'Đã lưu cài đặt người dùng.');}catch(error){document.querySelector('#settings-error').textContent=error.message;button.disabled=false;}};
}

